namespace Sunplus.Agent.Model.Entities.Base
{
    using System;
    using System.Collections.Generic;
    using System.Data;
    using System.Reflection;

    public static class _Extension
    {
        /// <summary>
        /// Create an enumerable from a data table.
        /// </summary>
        /// <param name="dataTable"></param>
        /// <param name="enumerable"></param>
        /// <param name="type"></param>
        public static IEnumerable<IEntity> AsEnumerable(this DataTable dataTable, Type type)
        {
            DataRowCollection rows = dataTable.Rows;

            ConstructorInfo constructor = type.GetConstructor(new Type[] { typeof(DataRow) });

            foreach (DataRow row in rows)
            {
                yield return constructor.Invoke(new object[] { row }) as IEntity;
            }
        }

        /// <summary>
        /// Create an enumerable from a data reader.
        /// </summary>
        /// <param name="reader"></param>
        /// <param name="enumerable"></param>
        /// <param name="type"></param>
        public static IEnumerable<IEntity> AsEnumerable(this IDataReader reader, Type type)
        {
            ConstructorInfo constructor = type.GetConstructor(new Type[] { typeof(IDataReader) });

            while (reader.Read())
            {
                yield return constructor.Invoke(new object[] { reader }) as IEntity;
            }
        }
    }
}